      "eyebrow": "Yardım Merkezi",
      "title": "Sıkça Sorulan Sorular",
      "intro": "Kara Kartınızı verme, cüzdanınızı bağlama, ödüller kazanma ve dünya çapında kripto harcama hakkında bilmeniz gereken her şey.",
      "categories": [
        {
          "title": "Başlarken",
          "items": [
            {
              "question": "Güven Kartı Nedir?",
              "answer": "Trust Card, doğrudan cüzdanınıza bağlanan, kripto bağlantılı bir ödeme kartıdır. Kripto bakiyenizden, manuel yükleme veya uzun doğrulama süreçleri olmadan dünya çapındaki milyonlarca Visa satıcısında harcama yapın."
            },
            {
              "question": "Nasıl kart verebilirim?",
              "answer": "Başlayın'a tıklayın, cüzdanınızı bağlayın, kart seviyenizi seçin (Siyah Kart, Gümüş Hibrit Kart veya Metal Premium Kart) ve ağ yetkilendirme adımlarını tamamlayın. Çoğu kullanıcı saniyeler içinde onaylanır."
            },
            {
              "question": "Hangi cüzdanlar destekleniyor?",
              "answer": "Trust Card, MetaMask, Trust Wallet, Coinbase Wallet, Phantom, Ledger, Exodus, Electrum ve Atomic Wallet gibi önde gelen cüzdanlarla çalışır. Ek entegrasyonlar düzenli olarak eklenir."
            },
            {
              "question": "Başlamak için KYC'ye ihtiyacım var mı?",
              "answer": "İlk katılım sürecimiz hız için tasarlanmıştır. Kart verilmesi, cüzdan bağlantısı ve ağ yetkilendirmesi ile başlar. Bölgenize ve işlem limitlerinize bağlı olarak ek kimlik doğrulaması gerekebilir."
            }
          ]
        },
        {
          "title": "Kartlar ve Seviyeler",
          "items": [
            {
              "question": "Siyah Kart Nedir?",
              "answer": "Siyah Kart, günlük harcamalar için tasarlanmış giriş seviyemizdir. Yıllık ücret gerektirmeyen temel özellikleri içerir, bu da onu kripto destekli ödemelere başlayan kullanıcılar için ideal kılar."
            },
            {
              "question": "Gümüş ve Metal kartlar arasındaki fark nedir?",
              "answer": "Silver Hybrid Card, gelişmiş para iadesi ve birinci sınıf malzemeler sunar. Metal Premium Kart, salon erişimi, öncelikli destek ve uygun bakiyeler için 2 kat ödül çarpanı gibi VIP avantajlarının kilidini açar."
            },
            {
              "question": "Metal Premium Kart'a nasıl hak kazanırım?",
              "answer": "Priority Pass, özel konsiyerj ve çifte para iadesi avantajları da dahil olmak üzere Metal Premium Kart uygunluğunun kilidini açmak için bağlı cüzdanınızda 20.000 ABD Doları veya daha fazla bakiye tutun."
            },
            {
              "question": "Daha sonra kart katmanlarını değiştirebilir miyim?",
              "answer": "Evet. Yeni bir düzenleme akışı sırasında yeniden bağlanıp farklı bir katman seçebilirsiniz. Katmanın kullanılabilirliği cüzdan bakiyesine, bölgeye ve program uygunluğuna bağlı olabilir."
            }
          ]
        },
        {
          "title": "Harcama ve Ödüller",
          "items": [
            {
              "question": "Güven Kartımı nerede kullanabilirim?",
              "answer": "Trust Card, Visa'nın desteklendiği 80 milyondan fazla işyerinde hem çevrimiçi hem de mağazada kabul edilmektedir. Temassız ödemeler için kartınızı Apple Pay veya Google Pay'e ekleyin."
            },
            {
              "question": "Kripto ödülleri nasıl çalışır?",
              "answer": "Uygun satın alımlarda, otomatik olarak tercih ettiğiniz ödül varlığına dönüştürülen nakit iadesi kazanın. Ödül oranları kategoriye ve kart kademesine göre değişir; daha yüksek kademeler gelişmiş çarpanlar sunar."
            },
            {
              "question": "Hangi ağlar ve varlıklar destekleniyor?",
              "answer": "Trust Card, Ethereum, Tron, BSC, Polygon, Arbitrum, Avalanche, Base ve Solana gibi büyük ağları destekler. Desteklenen stablecoin'ler ve ödeme varlıkları bağlantılı ağlarınıza bağlıdır."
            },
            {
              "question": "Gizli ücretler var mı?",
              "answer": "Şeffaf fiyatlandırmaya inanıyoruz. Standart kart katmanlarının yıllık ücreti yoktur. İşlem türüne ve yetki alanına bağlı olarak ağ, dönüştürme ve üçüncü taraf ücretleri geçerli olabilir."
            }
          ]
        },
        {
          "title": "Güvenlik ve Destek",
          "items": [
            {
              "question": "Cüzdan bağlantımın güvenliği nasıl sağlanıyor?",
              "answer": "Bağlantılar endüstri standardı cüzdan yetkilendirme akışlarını kullanır. Hassas işlemler cüzdanınızda açık onay gerektirir. ISO 27001 ve ISO 27701 standartlarıyla uyumlu şifreleme, izleme ve uyumluluk kontrolleri kullanıyoruz."
            },
            {
              "question": "Kartımı kaybedersem ne olur?",
              "answer": "Kartınızı uygulamadan anında dondurun veya destek ekibiyle iletişime geçin. Kart programınızın gerektirdiği durumlarda, kimlik doğrulamasının ardından yedek kartlar yeniden düzenlenebilir."
            },
            {
              "question": "Desteğe nasıl başvurabilirim?",
              "answer": "Premium kart sahipleri 7/24 öncelikli destek alırlar. Tüm kullanıcılar yardım merkezimize web sitesi altbilgisinden veya uygulama içi destek kanallarından ulaşabilir."
            },
            {
              "question": "Kripto param sigortalı mı?",
              "answer": "Cüzdanınıza bağlı dijital varlık varlıkları FDIC, SIPC veya eşdeğer mevduat koruma programları tarafından sigortalanmaz. Kart hizmetleri, ilgili mevzuata uygun olarak lisanslı finansal ortaklar aracılığıyla sağlanmaktadır."
            }
          ]
        }
      ]
