          "title": "安全与支持",
          "items": [
            {
              "question": "我的钱包连接如何安全？",
              "answer": "连接使用行业标准的钱包授权流程。敏感操作需要您钱包的明确批准。我们采用符合 ISO 27001 和 ISO 27701 标准的加密、监控和合规性控制。"
            },
            {
              "question": "如果我丢失卡怎么办？",
              "answer": "通过应用程序立即冻结您的卡或联系支持人员。根据您的卡计划的要求，可以在身份验证后重新签发替换卡。"
            },
            {
              "question": "如何联系支持人员？",
              "answer": "高级卡持卡人可获得 24/7 优先支持。所有用户都可以通过网站页脚或应用内支持渠道访问我们的帮助中心。"
            },
            {
              "question": "我的加密货币有保险吗？",
              "answer": "与您钱包相关的数字资产持有量不受 FDIC、SIPC 或同等存款保护计划的保险。卡服务由获得许可的金融合作伙伴根据适用法规提供。"
            }
          ]
